void MissingTexture::_Init()
{
	DebugEventStart(DEBUG_COLOR1,L"StartMissingTextureCreate");
	IDirect3DTexture9 *tex = DX8Wrapper::Create_DX8_Texture(missing_image_width,missing_image_height,WW3D_FORMAT_A8R8G8B8,TextureClass::MIP_LEVELS_ALL,D3DPOOL_MANAGED,false);
	RECT r;
	r.top = 0;
	r.left = 0;
	r.right = missing_image_width;
	r.bottom = missing_image_height;
	D3DLOCKED_RECT locked_rect;
	tex->LockRect(0,&locked_rect,&r,0);
	unsigned int xpos = 0;
	unsigned int ypos = missing_image_height;
	unsigned int total = 0;
	unsigned int *lockedbits = (unsigned int *)locked_rect.pBits;
	for (unsigned int i = 0;i < missing_image_run_count;i++)
	{
		unsigned int color = missing_image_color_values[i];
		unsigned char run = missing_image_run_lengths[i] + 1;
		if (run > 0)
		{
			total += run;
			do
			{
				*lockedbits = color;
				lockedbits++;
				xpos++;
				if (xpos >= missing_image_width)
				{
					ypos--;
					xpos = 0;
					lockedbits = (unsigned int *)((char *)locked_rect.pBits + 4 * ypos * (locked_rect.Pitch >> 2));
				}
				run--;
			} while (run);
		}
	}
	tex->UnlockRect(0);
	IDirect3DSurface9 *surface;
	IDirect3DSurface9 *surface2;
	for (unsigned int i = 1;i < tex->GetLevelCount();i++)
	{
		tex->GetSurfaceLevel(i - 1,&surface);
		tex->GetSurfaceLevel(i,&surface2);
		D3DXLoadSurfaceFromSurface(surface2,0,0,surface,0,0,5,0);
		surface->Release();
		surface2->Release();
	}
	_MissingTexture = tex;
	DebugEventEnd();
}
void MissingTexture::_Deinit()
{
	_MissingTexture->Release();
	_MissingTexture = 0;
}
IDirect3DTexture9 *MissingTexture::_Get_Missing_Texture()
{
	_MissingTexture->AddRef();
	return _MissingTexture;
}
IDirect3DSurface9 *MissingTexture::_Create_Missing_Surface()
{
	IDirect3DSurface9 *surface;
	IDirect3DSurface9 *surface2;
	_MissingTexture->GetSurfaceLevel(0,&surface);
	D3DSURFACE_DESC desc;
	surface->GetDesc(&desc);
	DX8Wrapper::D3DDevice->CreateOffscreenPlainSurface(desc.Width,desc.Height,desc.Format,D3DPOOL_SCRATCH,&surface2,0);
	D3DLOCKED_RECT src,dst;
	unsigned int formatsize = 4;
	if ((desc.Format == D3DFMT_A4R4G4B4)|| (desc.Format == D3DFMT_R5G6B5))
	{
		formatsize = 2;
	}
	surface2->LockRect(&dst,NULL,0);
	surface->LockRect(&src,NULL,D3DLOCK_READONLY);
	memcpy(dst.pBits,src.pBits,desc.Width * desc.Height * formatsize);
	surface2->UnlockRect();
	surface->UnlockRect();
	surface->Release();
	return surface2;
}
